// Ops announce relay (DR-0155): a GitHub runner filed an incident on the
// ledger; this pushes it to the family's phones via the NAS ntfy container.
// The TOPIC IS PINNED server-side ('darrell' — the topic the family phones
// already subscribe to) so a caller can never spray arbitrary topics; the
// caller supplies only title/message/url/priority, each capped/validated.
// this.helpers.httpRequest per LESSONS P17 (Code nodes have no global fetch).
const out = [];
for (const item of items) {
  const b = (item.json && (item.json.body || item.json)) || {};
  const title = String(b.title || 'PoeTech ops').replace(/[\r\n]/g, ' ').slice(0, 120);
  const message = String(b.message || 'ops event').slice(0, 900);
  const rawUrl = String(b.url || '');
  const click = /^https:\/\/(github\.com|poetech\.us)\//.test(rawUrl) ? rawUrl.slice(0, 500) : '';
  const priority = ['1', '2', '3', '4', '5'].includes(String(b.priority)) ? String(b.priority) : '4';
  let delivered = false;
  let detail = '';
  try {
    const headers = { 'x-title': title, 'x-priority': priority, 'x-tags': 'rotating_light' };
    if (click) headers['x-click'] = click;
    await this.helpers.httpRequest({
      url: 'http://ntfy:80/darrell',
      method: 'POST',
      body: message,
      timeout: 10000,
      headers,
    });
    delivered = true;
  } catch (e) {
    // Best-effort by design: the incident is already on the GitHub ledger —
    // the record — so a push failure must never error the webhook.
    detail = String((e && e.message) || e).slice(0, 200);
  }
  out.push({ json: { delivered, detail } });
}
return out;
